<?php
declare(strict_types=1);
require dirname(__DIR__) . '/rado-system/lib/app.php';
session_name('rado_admin');session_set_cookie_params(['httponly'=>true,'secure'=>!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off','samesite'=>'Strict','path'=>'/']);session_start();if(empty($_SESSION['admin_id'])){http_response_code(403);exit('Forbidden');}$pdo=rado_db();
if(isset($_GET['json'])){$drivers=$pdo->query("SELECT d.user_id,u.full_name,d.plate_number,p.latitude,p.longitude,p.heading,p.speed_kph,p.last_seen_at FROM drivers d JOIN users u ON u.id=d.user_id JOIN driver_presence p ON p.driver_id=d.user_id WHERE d.status='approved' AND p.is_online=1 AND p.latitude IS NOT NULL AND p.longitude IS NOT NULL AND p.last_seen_at>=DATE_SUB(NOW(),INTERVAL 3 MINUTE)")->fetchAll();$trips=$pdo->query("SELECT id,status,pickup_lat,pickup_lng,destination_lat,destination_lng,pickup_label,destination_label,driver_id,estimated_fare FROM trips WHERE status IN('searching','driver_assigned','driver_arriving','arrived','in_progress') ORDER BY requested_at DESC LIMIT 200")->fetchAll();foreach($drivers as &$d)$d['last_seen_at_jalali']=rado_jalali_datetime((string)$d['last_seen_at']);rado_json(200,['ok'=>true,'drivers'=>$drivers,'trips'=>$trips,'time'=>rado_jalali_datetime(null,true)]);}
?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>نقشه زنده RADO</title><link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css"><style>html,body{height:100%;margin:0;font-family:Tahoma;background:#111}#map{height:100%}.top{position:fixed;z-index:9999;top:12px;right:12px;left:12px;background:#171717eF;color:white;border-radius:18px;padding:12px 16px;display:flex;align-items:center;gap:12px;box-shadow:0 8px 30px #0005}.logo{font-size:24px;font-weight:900}.gold{color:#f5b400}.status{margin-right:auto;font-size:11px;color:#ddd}.back{color:white;text-decoration:none;background:#333;padding:7px 10px;border-radius:10px}</style></head><body><div class="top"><div class="logo">R<span class="gold">A</span>DO LIVE</div><div>رانندگان و سفرهای فعال بانه</div><div id="status" class="status">در حال اتصال…</div><a class="back" href="/admin/dispatch.php">عملیات</a></div><div id="map"></div><script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script><script>const map=L.map('map',{zoomControl:true}).setView([35.9968,45.8853],14);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap'}).addTo(map);const layers=L.layerGroup().addTo(map);function esc(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));}async function load(){try{const r=await fetch('/admin/live-map.php?json=1',{cache:'no-store'});const d=await r.json();layers.clearLayers();for(const x of d.drivers){const m=L.circleMarker([Number(x.latitude),Number(x.longitude)],{radius:9,color:'#171717',weight:3,fillColor:'#f5b400',fillOpacity:1}).addTo(layers);m.bindPopup('<b>'+esc(x.full_name)+'</b><br>پلاک: '+esc(x.plate_number)+'<br>'+esc(x.last_seen_at_jalali));}for(const t of d.trips){const c=t.status==='searching'?'#e53935':'#1565c0';L.circleMarker([Number(t.pickup_lat),Number(t.pickup_lng)],{radius:6,color:c,fillOpacity:.8}).addTo(layers).bindPopup('<b>مبدا سفر</b><br>'+esc(t.pickup_label)+'<br>'+esc(t.status));L.circleMarker([Number(t.destination_lat),Number(t.destination_lng)],{radius:5,color:'#8e24aa',fillOpacity:.75}).addTo(layers).bindPopup('<b>مقصد</b><br>'+esc(t.destination_label));}document.getElementById('status').textContent=(d.drivers?.length??0)+' راننده آنلاین · '+(d.trips?.length??0)+' سفر فعال · '+d.time;}catch(e){document.getElementById('status').textContent='خطا در بروزرسانی';}}load();setInterval(load,8000);</script></body></html>